`timescale 1ns/1ps
module xsil_rocc (
  input             clk,
  input             rst_n,

  // RoCC command channel (Decoupled)
  input             cmd_valid,
  output reg        cmd_ready,
  input      [31:0] cmd_inst,
  input      [31:0] cmd_rs1,
  input      [31:0] cmd_rs2,

  // Adapter: current destination-register value (rd-as-source).
  // Stock RoCC only forwards rs1/rs2 values when xs1/xs2 are set.
  input      [31:0] cmd_rsd,

  // RoCC response channel (Decoupled)
  output reg        resp_valid,
  input             resp_ready,
  output reg  [4:0] resp_rd,
  output reg [31:0] resp_data,

  // Busy while a command is in flight (for fences / tracking).
  output reg        busy
);

  localparam S_IDLE  = 2'd0;
  localparam S_BUSY  = 2'd1;
  localparam S_RESP  = 2'd2;

  function automatic [31:0] xsil_clz;
    input [31:0] a;
    integer i;
    reg found;
    begin
      xsil_clz = 32'd32;
      found = 1'b0;
      for (i = 31; i >= 0; i = i - 1) begin
        if (!found && a[i]) begin
          xsil_clz = 31 - i;
          found = 1'b1;
        end
      end
    end
  endfunction

  wire match_xmac = cmd_valid && ((cmd_inst & 32'hfe00707f) == 32'h0200000b);
  wire match_any = match_xmac;

  reg match_xmac_q;
  reg [31:0] rs1_q, rs2_q, rsd_q;
  reg [31:0] result_d;
  reg  [4:0] rd_q;
  reg  [1:0] state;

  always @* begin
    result_d = 32'd0;
    case (1'b1)
      match_xmac_q: result_d = ((rsd_q) + (((rs1_q) * (rs2_q))));
      default: result_d = 32'd0;
    endcase
  end

  always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
      state <= S_IDLE;
      cmd_ready <= 1'b0;
      resp_valid <= 1'b0;
      resp_rd <= 5'd0;
      resp_data <= 32'd0;
      busy <= 1'b0;
      rs1_q <= 32'd0;
      rs2_q <= 32'd0;
      rsd_q <= 32'd0;
      rd_q <= 5'd0;
      match_xmac_q <= 1'b0;
    end else begin
      cmd_ready <= 1'b0;

      case (state)
        S_IDLE: begin
          resp_valid <= 1'b0;
          busy <= 1'b0;
          if (cmd_valid && match_any) begin
            cmd_ready <= 1'b1;
            match_xmac_q <= match_xmac;
            rs1_q <= cmd_rs1;
            rs2_q <= cmd_rs2;
            rsd_q <= cmd_rsd;
            rd_q <= cmd_inst[11:7];
            busy <= 1'b1;
            state <= S_BUSY;
          end
          // Unrecognized opcodes: leave cmd_ready low so the BFM times out /
          // the core can treat as illegal — we do not accept them.
        end

        S_BUSY: begin
          busy <= 1'b1;
          // One compute cycle with stable latched operands.
          state <= S_RESP;
        end

        S_RESP: begin
          busy <= 1'b1;
          resp_valid <= 1'b1;
          resp_rd <= rd_q;
          resp_data <= result_d;
          if (resp_valid && resp_ready) begin
            resp_valid <= 1'b0;
            busy <= 1'b0;
            match_xmac_q <= 1'b0;
            state <= S_IDLE;
          end
        end

        default: state <= S_IDLE;
      endcase
    end
  end

endmodule
